import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.LX5S0jbT.js";const m=JSON.parse('{"title":"CLI Integration","description":"","frontmatter":{},"headers":[],"relativePath":"cli-integration.md","filePath":"cli-integration.md"}'),i={name:"cli-integration.md"};function o(r,e,d,p,l,h){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="cli-integration" tabindex="-1">CLI Integration <a class="header-anchor" href="#cli-integration" aria-label="Permalink to &quot;CLI Integration&quot;">​</a></h1><p>By default, running <code>pi</code> opens the interactive terminal interface. When input or output is piped or redirected, Pi uses print mode instead. You can also select print, JSON, or RPC mode explicitly for scripts and applications.</p><p>All four modes use the same agent, sessions, resources, and tools. The mode determines how input enters Pi, how output is exposed, and whether the process remains available for more commands.</p><p>The SDK is not a CLI mode. It embeds the agent directly in a Node.js or Bun process. See the <a href="./sdk.html">SDK</a> when direct TypeScript access is preferable to a process boundary.</p><h2 id="choose-a-mode" tabindex="-1">Choose a mode <a class="header-anchor" href="#choose-a-mode" aria-label="Permalink to &quot;Choose a mode&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Interface</th><th>Lifetime</th><th>Use it when</th></tr></thead><tbody><tr><td>Interactive</td><td>Terminal UI</td><td>Until the user exits</td><td>A person is working with Pi directly</td></tr><tr><td>Print</td><td>Final text on stdout</td><td>One invocation</td><td>A script needs the final assistant response</td></tr><tr><td>JSON</td><td>JSONL events on stdout</td><td>One invocation</td><td>A process needs structured progress from a run</td></tr><tr><td>RPC</td><td>JSONL commands, responses, and events</td><td>Long-lived</td><td>A process needs bidirectional control</td></tr></tbody></table><p>CLI options still select the working directory, model, tools, resources, and session persistence independently of the mode. See <a href="./cli.html">Command Line</a> for the complete startup options.</p><h2 id="print-to-stdout" tabindex="-1">Print to stdout <a class="header-anchor" href="#print-to-stdout" aria-label="Permalink to &quot;Print to stdout&quot;">​</a></h2><p>Print mode runs the supplied prompts, writes the final assistant text to stdout, and exits:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --print</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Summarize the changes in this repository&quot;</span></span></code></pre></div><p>Use print mode when only the final text is needed, including command substitution, pipelines, and one-shot jobs. Intermediate events are not exposed.</p><p>Print mode writes errors to stderr. A final assistant response with an <code>error</code> or <code>aborted</code> stop reason produces a nonzero exit status. A response cut off at the model&#39;s output token limit (<code>length</code> stop reason) still prints its partial text to stdout, writes a warning to stderr, and produces a nonzero exit status.</p><p>When no mode is selected explicitly, non-TTY stdin or stdout also selects print mode. This allows piped input and output without adding <code>--print</code>.</p><h2 id="stream-json-events" tabindex="-1">Stream JSON events <a class="header-anchor" href="#stream-json-events" aria-label="Permalink to &quot;Stream JSON events&quot;">​</a></h2><p>JSON mode writes a session header followed by agent and session events as newline-delimited JSON:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Review this repository&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events.jsonl</span></span></code></pre></div><p>This is structured event output, not a single JSON result or a constraint on the format of the model’s response.</p><p>All prompts are supplied when the process starts. The process streams events for that run and then exits; it does not accept later commands.</p><p>A failed or aborted assistant response appears in the event stream but does not by itself produce a nonzero exit status. Inspect the events when success or failure matters. Pi still exits nonzero if the invocation throws an error.</p><p>Streaming <code>message_update</code> records contain deltas rather than a growing message snapshot. Assemble live output from the delta events, then replace it with the authoritative message from <code>message_end</code>.</p><p><code>agent_end</code> can be followed by automatic recovery or queued work. <code>agent_settled</code> marks the end of automatic work for the current run.</p><p>Stdout is reserved for JSONL. Diagnostics and application logging are written to stderr. See <a href="./json.html">JSON Event Stream</a> for framing, event shapes, and reconstruction rules.</p><h2 id="control-pi-with-rpc" tabindex="-1">Control Pi with RPC <a class="header-anchor" href="#control-pi-with-rpc" aria-label="Permalink to &quot;Control Pi with RPC&quot;">​</a></h2><p>RPC mode keeps Pi running while another process sends commands and receives responses and events:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rpc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-session</span></span></code></pre></div><p>Commands are JSON objects written to stdin. Responses and events are JSON objects written to stdout. Every record occupies one line.</p><p>Add an <code>id</code> to commands that need correlation. The matching response repeats that ID. Events generally have no command ID because they describe session activity rather than one request.</p><p>A successful <code>prompt</code> response means the prompt was accepted, queued, or handled. It does not mean the run completed. Continue consuming events through <code>agent_settled</code> when completion matters.</p><p>RPC commands can change models, inspect state, manage sessions, run shell commands, and answer extension UI requests.</p><p>Extension dialogs form a request-response subprotocol. Other extension UI updates are notifications that a client may display or ignore. TUI-only extension capabilities are unavailable or degraded outside interactive mode.</p><p>For Node.js or TypeScript integrations, prefer <code>RpcClient</code> from <code>@earendil-works/pi-coding-agent</code>. It starts a Pi RPC child process, correlates requests, exposes typed command methods, and delivers session events to listeners.</p><p>The <a href="https://github.com/earendil-works/pi/blob/main/packages/coding-agent/examples/rpc-client.ts" target="_blank" rel="noreferrer">RPC client example</a> sends one prompt, streams text and tool activity, waits for <code>agent_settled</code>, and shuts down the child process. It is included in the repository’s TypeScript checks.</p><p><code>RpcClient.promptAndWait()</code> installs its event listener before sending the prompt, avoiding a race with fast completions. For separate operations, subscribe before calling <code>prompt()</code> and call <code>waitForIdle()</code> only while a run is active.</p><p>The client requires a path to a runnable Pi CLI. The repository example points at <code>dist/cli.js</code>, so the package must be built before that example runs from a checkout.</p><p>If you are building a client without <code>RpcClient</code>, start with <a href="./rpc.html">RPC Protocol</a>, then use <a href="./rpc-commands.html">RPC Commands</a> and <a href="./json.html">JSON Event Stream</a> as the wire references.</p><h2 id="fork-and-rebrand-pi" tabindex="-1">Fork and rebrand Pi <a class="header-anchor" href="#fork-and-rebrand-pi" aria-label="Permalink to &quot;Fork and rebrand Pi&quot;">​</a></h2><p>A source fork can change the CLI name and configuration directory through <code>package.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;piConfig&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-agent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;configDir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.my-agent&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Change the top-level <code>bin</code> field to set the executable name. These settings affect the CLI banner, configuration paths, and derived environment variable names.</p><h2 id="examples-and-references" tabindex="-1">Examples and references <a class="header-anchor" href="#examples-and-references" aria-label="Permalink to &quot;Examples and references&quot;">​</a></h2><ul><li><a href="https://github.com/earendil-works/pi/blob/main/packages/coding-agent/examples/rpc-client.ts" target="_blank" rel="noreferrer">RPC client</a>: typed Node.js integration</li><li><a href="https://github.com/earendil-works/pi/blob/main/packages/coding-agent/examples/rpc-extension-ui.ts" target="_blank" rel="noreferrer">RPC extension UI</a>: custom terminal client with extension dialogs</li><li><a href="./cli.html">Command Line</a>: startup options and mode selection</li><li><a href="./json.html">JSON Event Stream</a>: JSON event reference</li><li><a href="./rpc.html">RPC Protocol</a>: RPC lifecycle, framing, errors, and shutdown</li><li><a href="./rpc-commands.html">RPC Commands</a>: command and response reference</li><li><a href="./rpc-extension-ui.html">RPC Extension UI</a>: extension interaction subprotocol</li><li><a href="https://github.com/earendil-works/pi/tree/main/packages/coding-agent/examples/sdk" target="_blank" rel="noreferrer">SDK examples</a>: in-process TypeScript integrations</li></ul>`,41)])])}const u=t(i,[["render",o]]);export{m as __pageData,u as default};
